#!/usr/bin/env python3
"""Early VME operands with and without legitimate queued vector producers."""
import argparse,hashlib,json,subprocess
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser(__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);native=R/'build/saturn-timing-native-v1';sdk=R/'build/saturn-timing-sdk-v1';base=(R/'timing/saturn_timing_scrub.cpp').read_text().split('template<class M>static void run',1)[0];root=(native/'compute/model/VSaturnCompute___024root.h').read_text();prefix='SaturnShuttleUnit__DOT__vu__DOT__';members={'issue':prefix+'_vos_io_iss_valid','mm':prefix+'vos__DOT__mm','rv1':prefix+'_vos_io_rvs1_valid','rv2':prefix+'_vos_io_rvs2_valid','tile0':prefix+'vopu__DOT__clusters_0_0__DOT__cells_0_0__DOT__regs_0'};assert all(n in root for n in members.values());code=base+'\n#include <vector>\n'
 code+='static void packet(VSaturnCompute&m,unsigned sequence,unsigned slot,bool valid){m.io_ex_valid=valid;m.io_ex_fire=valid;m.io_ex_uop_pc=0x80002000+4*slot;m.io_ex_vconfig_vl=1;m.io_ex_vconfig_vtype_vsew=0;m.io_ex_vconfig_vtype_vlmul_mag=0;m.io_ex_vconfig_vtype_tm=1;m.io_ex_vconfig_vtype_tk=1;m.io_ex_vconfig_vtype_vtwiden=3;if(sequence&&slot<2){m.io_ex_uop_inst=slot?0x5e01b857u:0x5e03b457u;m.io_ex_vconfig_vtype_vtwiden=0;}else m.io_ex_uop_inst=slot==(sequence?2:0)?0x43e06057u:0xf2880077u;}\n'
 code+='static void run(unsigned producers,unsigned seed,bool corrupt){auto ctx=std::make_unique<VerilatedContext>();ctx->threads(1);ctx->randSeed(seed);ctx->randReset(2);VSaturnCompute m(ctx.get());inputs(m);m.reset=1;m.clock=0;m.eval();for(unsigned n=0;n<2;n++){m.clock=1;m.eval();m.clock=0;m.eval();}std::array<std::uint32_t,16>old;'
 for n in range(16):code+='old['+str(n)+']=m.rootp->'+prefix+'vopu__DOT__clusters_0_0__DOT__cells_0_0__DOT__regs_'+str(n)+';'
 code+='m.reset=0;unsigned first_mm=~0u,operand_wait_edges=0,mm_count=0;for(unsigned edge=0;edge<160;edge++){packet(m,producers,edge,edge<(producers?4:2));m.eval();auto sweep_state=sweep(m);bool mm=m.rootp->'+members['mm']+',fire=m.rootp->'+members['issue']+';bool reads=m.rootp->'+members['rv1']+'||m.rootp->'+members['rv2']+';if(mm&&reads&&sweep_state.active){require(!fire,"VME operand read escaped source reset gate");++operand_wait_edges;}if(mm&&fire){if(first_mm==~0u)first_mm=edge;++mm_count;require(!sweep_state.active,"VME MAC issued before source scrub completion");require(ram(m,16,0)==(producers?7u:0u),"VME A operand did not honor prior vector write");require(ram(m,32,0)==(producers?3u:0u),"VME B operand did not honor prior vector write");}m.clock=1;m.eval();m.clock=0;m.eval();}require(mm_count==1&&first_mm>=64,"Early VME sequence did not issue exactly once after scrub");require((m.rootp->'+members['tile0']+'^(corrupt?1u:0u))==(producers?21u:0u),"VME MAC result contradicts explicit zero tile and source operands");'
 for n in range(1,16):code+='require(m.rootp->'+prefix+'vopu__DOT__clusters_0_0__DOT__cells_0_0__DOT__regs_'+str(n)+'==old['+str(n)+'],"Untouched tile entry changed");'
 code+='std::cout<<"RESET_VME_RESULT {\\"seed\\":"<<seed<<",\\"prior_vector_producers\\":"<<producers<<",\\"first_MM_edge\\":"<<first_mm<<",\\"operand_wait_edges_during_scrub\\":"<<operand_wait_edges<<",\\"C00\\":"<<m.rootp->'+members['tile0']+'<<",\\"explicit_tile_zero\\":true,\\"other_sampled_entries_preserved\\":true}\\n";}\nint main(int argc,char**argv){try{bool corrupt=argc==2&&std::string(argv[1])=="--corrupt-result";for(unsigned seed:{0u,17u})for(unsigned producers:{0u,1u})run(producers,seed,corrupt);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<\'\\n\';return 2;}}\n'
 source=R/'timing/saturn_timing_reset_vme.cpp';source.write_text(code);tool=Path('/scratch/eygao/iris-cy/.conda-env/share/verilator/include');command=['/usr/bin/g++','-O3','-std=c++20','-I'+str(tool),'-I'+str(tool/'vltstd')]+['-I'+str(native/k/'model')for k in ['compute','rocket']]+[str(source),str(sdk/'sdk/libiris_saturn_timing.a'),'-pthread','-latomic','-o',str(out/'early-vme')]
 with(out/'build.log').open('w')as log:subprocess.run(command,stdout=log,stderr=subprocess.STDOUT,check=True)
 q=subprocess.run([str(out/'early-vme')],capture_output=True,text=True,timeout=60);(out/'stdout').write_text(q.stdout);(out/'stderr').write_text(q.stderr)
 if q.returncode:raise RuntimeError('Early VME proof failed; preserved source/output')
 results=[json.loads(x.split(' ',1)[1])for x in q.stdout.splitlines()if x.startswith('RESET_VME_RESULT ')];assert len(results)==4;bad=subprocess.run([str(out/'early-vme'),'--corrupt-result'],capture_output=True,text=True,timeout=60);(out/'corrupt-result.stderr').write_text(bad.stderr);assert bad.returncode==2;report={'schema':'iris.saturn_early_vme_operand_proof.v1','argv':command,'results':results,'input_sha256':{str(p):sha(p)for p in[Path(__file__),source,R/'timing/saturn_timing_scrub.cpp',sdk/'build.json',sdk/'sdk/libiris_saturn_timing.a']},'native_sha256':sha(out/'early-vme'),'internal_state_or_memory_injected':False,'tile_initialization':'Actual issued VTZERO of C00, never a model constructor clear','corrupted_C00_rejected':True,'hardware_contacted':False};(out/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'results':results,'report_sha256':sha(out/'report.json')}))
if __name__=='__main__':main()
